//! Golden compatibility tests: fixtures generated by the originating
//! project's own code (see tests/fixtures/README.md) decode here, and what
//! this crate produces is byte-identical (objects) or opens there (sealed
//! objects; see the `golden_out` example for that direction).

mod common;
use common::*;
use replicix_chunkfmt::e2e::{decrypt_object, encrypt_object};
use replicix_chunkfmt::format::{decode_object, encode_object};
use replicix_chunkfmt::{unlock, ChunkHash, ChunkLayout, CompressionSetting, KeyringBlock};
use serde_json::Value;

#[test]
fn objects_decode_and_re_encode_byte_for_byte() {
    let mut n = 0;
    for name in NAMES {
        let plain = plain(name);
        for (suffix, setting) in SETTINGS {
            let obj =
                std::fs::read(fixtures().join(format!("objects/{name}.{suffix}.cch1"))).unwrap();
            assert_eq!(
                decode_object(&obj).unwrap(),
                plain,
                "decode {name}.{suffix}"
            );
            let ours =
                encode_object(&plain, setting.parse::<CompressionSetting>().unwrap()).unwrap();
            assert_eq!(ours, obj, "encode {name}.{suffix}");
            n += 1;
        }
    }
    assert_eq!(n, 15);
}

#[test]
fn chunk_hashes_match() {
    let want: Value =
        serde_json::from_slice(&std::fs::read(fixtures().join("hashes.json")).unwrap()).unwrap();
    for name in NAMES {
        let p = plain(name);
        assert_eq!(want[name]["plain"], ChunkHash::of(&p).to_hex(), "{name}");
        assert_eq!(
            want[name]["keyed7"],
            ChunkHash::keyed(&[7; 32], &p).to_hex(),
            "{name}"
        );
    }
}

#[test]
fn slices_match() {
    let want: Vec<Value> =
        serde_json::from_slice(&std::fs::read(fixtures().join("slices.json")).unwrap()).unwrap();
    assert!(!want.is_empty());
    for case in want {
        let (cs, off, len) = (
            case["chunk_size"].as_u64().unwrap() as u32,
            case["offset"].as_u64().unwrap(),
            case["len"].as_u64().unwrap(),
        );
        let l = ChunkLayout::new(cs);
        let got: Vec<Value> = l
            .slices(off, len)
            .map(|s| serde_json::json!([s.index, s.offset, s.len]))
            .collect();
        assert_eq!(Value::Array(got), case["slices"], "{case}");
        assert_eq!(case["count"], l.chunk_count(off + len));
        if off + len > 0 {
            assert_eq!(
                case["last_len"],
                l.chunk_len(off + len, l.chunk_count(off + len) - 1)
            );
        }
    }
}

#[test]
fn keyring_unlocks_and_derives_identical_keys() {
    let dir = fixtures().join("e2e");
    let block: KeyringBlock =
        serde_json::from_slice(&std::fs::read(dir.join("keyring.json")).unwrap()).unwrap();
    let pass = std::fs::read_to_string(dir.join("passphrase.txt")).unwrap();
    assert_eq!(pass, PASSPHRASE);
    let keys = unlock::<OriginDomain>(&block, &pass).unwrap();
    assert!(replicix_chunkfmt::unlock::<OriginDomain>(&block, "wrong").is_err());
    let text = plain("text");
    let h = keys.hash(&text);
    let got = derived(
        &keys.addressing_key()[..],
        &keys.gossip_secret()[..],
        &|n| keys.dek(n).to_vec(),
        &keys.pin_fingerprint(UUID),
        &h.to_hex(),
    );
    let want: Value =
        serde_json::from_slice(&std::fs::read(dir.join("derived.json")).unwrap()).unwrap();
    assert_eq!(got, want);

    // The envelope an origin-made sealed chunk uses opens here.
    let sealed = std::fs::read(dir.join("sealed_text.bin")).unwrap();
    let opened = decrypt_object(&keys.dek("p0"), &h.0, &sealed).unwrap();
    assert_eq!(decode_object(&opened).unwrap(), text);
    assert!(decrypt_object(&keys.dek("p1"), &h.0, &sealed).is_err());
    // And ours round-trips under the same key and AAD.
    let mine = encrypt_object(&keys.dek("p0"), &h.0, &opened).unwrap();
    assert_ne!(mine, sealed, "fresh nonce");
    assert_eq!(
        decrypt_object(&keys.dek("p0"), &h.0, &mine).unwrap(),
        opened
    );
}

/// A different domain derives different keys from the same master.
#[test]
fn the_domain_separates_hierarchies() {
    let dir = fixtures().join("e2e");
    let block: KeyringBlock =
        serde_json::from_slice(&std::fs::read(dir.join("keyring.json")).unwrap()).unwrap();
    let a = unlock::<OriginDomain>(&block, PASSPHRASE).unwrap();
    let b = unlock::<replicix_chunkfmt::ReplicixDomain>(&block, PASSPHRASE).unwrap();
    assert_ne!(a.addressing_key(), b.addressing_key());
    assert_ne!(a.gossip_secret(), b.gossip_secret());
    assert_ne!(a.pin_fingerprint(UUID), b.pin_fingerprint(UUID));
}
